package com.aoo.bcg.mahjong;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class MahjongRegionRulePoliciesTest{@Test void hbySourceSemanticsAreGenericDataPolicies(){for(int i=0;i<4;i++)assertEquals(new int[]{1,2,3,5}[i],MahjongRegionRulePolicies.baseUnit(Map.of("diFen",i)));for(int i=0;i<4;i++)assertEquals(new long[]{30,50,100,Long.MAX_VALUE}[i],MahjongRegionRulePolicies.scoreCap(Map.of("fengDing",i)));assertEquals(12,MahjongRegionRulePolicies.nextWildcard(11));assertEquals(11,MahjongRegionRulePolicies.nextWildcard(19));assertEquals(30,MahjongRegionRulePolicies.applyUnitAndCap(99,Map.of("diFen",0,"fengDing",0)));MahjongRegionRuntimeProfile p=MahjongRegionRuntimeProfiles.find("hbyxmj").orElseThrow();assertEquals(Set.of("diFen","fangjian","fengDing","gaoji","jiesan","kexuanwanfa","moshi","paymentRoomCardType","playerMinNum","playerNum","setCount","wanfa","xianShi"),p.allowedCreateFields());assertTrue(p.ruleComponents().contains("wildcard"));assertTrue(p.lifecycleComponents().contains("wildcard-resolution"));}}
